<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientPolicyUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientPolicyUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withPolicyUri,
 * getPolicyUri/policyUri accessors, and isPolicyUriChanged with/without original.
 */
class TrustedClientPolicyUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPolicyUri creates a new instance with the PolicyUri set
     * from a string value, and getPolicyUri returns the primitive string.
     */
    public function testWithPolicyUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientPolicyUriAccessorUnitTest();

        // Act
        $result = $holder->withPolicyUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getPolicyUri());
    }
    /**
     * Asserts that withpolicyUri has access to the value object
     * from a string value, and getPolicyUri returns the primitive string.
     */
    public function testWithPolicyUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientPolicyUriAccessorUnitTest();

        // Act
        $result = $holder->withPolicyUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->policyUri()->value());
    }
    public function testChangedPolicyUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientPolicyUriAccessorUnitTest();
        $original = $holder->withPolicyUri('one');
        $same = $holder->withPolicyUri('one');
        $modified = $holder->withPolicyUri('other');

        // Act
        $unchanged = $holder->isPolicyUriChanged();
        $withSame = $original->isPolicyUriChanged($same);
        $withDiferent = $original->isPolicyUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientPolicyUriAccessorUnitTest
{
    use TrustedClientPolicyUriAccessor;
}
